const CHECKBOOK_TITLE = "The Checkbook of Faith - Spurgeon";
function cbRefObj(s){ const m=String(s).match(/^(.+?)\s+(\d+):/); const b=m?m[1]:String(s); const c=m?parseInt(m[2],10):1; return {l:s,q:s,k:s,b,c}; }
function buildCheckbookBook(days,title){
  const paras=[]; const scenes=[];
  (days||[]).forEach((d,i)=>{
    const start=paras.length;
    paras.push(`Day ${i+1} \u00b7 ${d.t}  [${d.ref}]`);
    (d.body||[]).forEach(p=>paras.push(p));
    scenes.push({s:start,e:paras.length-1,c:[cbRefObj(d.ref)]});
  });
  return {id:"checkbook",title,paras,scenes};
}
function buildVerseListBook(items, title, id, asHeading){
  const paras=[]; const scenes=[];
  (items||[]).forEach(it=>{
    const start=paras.length;
    if(asHeading){ paras.push("\u00a7\u00a7 "+it.n); if(it.a) paras.push(it.a); }
    else { paras.push(`${it.n}  [${it.a}]`); }
    scenes.push({s:start,e:paras.length-1,c:[]});
  });
  return {id,title,paras,scenes};
}
