function getTimeSlot(ts) {
  const h = new Date(ts).getHours();
  if (h < 11) return "morning";
  if (h < 16) return "midday";
  return "evening";
}
function MiniTripleArc({f=[0,0,0], size=34, ring=null}) {
  const colors = ["#2a5ab8","#3aaa55","#e05a18"];
  const cx = size/2, cy = size/2;
  const radii = [size*0.42, size*0.30, size*0.18];
  const sw = size*0.10;
  const seg = (r, frac, col, key) => {
    if (frac <= 0) return null;
    const a1 = Math.min(359.9, frac*360);
    const p = a => [cx + r*Math.cos((a-90)*Math.PI/180), cy + r*Math.sin((a-90)*Math.PI/180)];
    const [x0,y0] = p(0), [x1,y1] = p(a1);
    const lg = a1 > 180 ? 1 : 0;
    return <path key={key} d={`M ${x0.toFixed(2)} ${y0.toFixed(2)} A ${r} ${r} 0 ${lg} 1 ${x1.toFixed(2)} ${y1.toFixed(2)}`}
      stroke={col} strokeWidth={sw} fill="none" strokeLinecap="round"/>;
  };
  return (
    <svg width={size} height={size} style={{display:"block",overflow:"visible"}}>
      {ring && <circle cx={cx} cy={cy} r={size*0.52} stroke={ring} strokeWidth={1.5} fill="none"/>}
      {radii.map((r,i)=><circle key={"t"+i} cx={cx} cy={cy} r={r} stroke={`rgba(${C.ink},0.08)`} strokeWidth={sw} fill="none"/>)}
      {radii.map((r,i)=>seg(r, f[i], colors[i], "s"+i))}
      {f[0]>=1 && f[1]>=1 && f[2]>=1 && (
        <text x={cx} y={cy} textAnchor="middle" dominantBaseline="central"
          fontSize={size*0.34} style={{filter:"drop-shadow(0 0 2px rgba(212,160,23,0.7))"}}>⭐</text>
      )}
    </svg>
  );
}

function YearHeat2({entries, today, onOpenDay=()=>{}}) {
  const sum = iso => (entries[iso]||[]).reduce((t,e)=>t+(e.minutes||0),0);
  const isoOf = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
  const [sel, setSel] = React.useState(null);
  // window: from first entry (Sunday-aligned) to today, capped at 52 weeks
  const withData = Object.keys(entries).filter(k=>/^\d{4}-\d{2}-\d{2}$/.test(k) && sum(k)>0).sort();
  const firstIso = withData[0] || today;
  const end = new Date(today+"T00:00:00");
  let start = new Date(firstIso+"T00:00:00");
  start.setDate(start.getDate() - start.getDay());            // back to Sunday
  let weeks = Math.max(1, Math.ceil(((end - start)/86400000 + 1) / 7));
  if (weeks > 52) {
    start = new Date(end); start.setDate(start.getDate() - start.getDay() - 51*7);
    weeks = 52;
  }
  // levels from quartiles of nonzero minutes in window
  const winVals = [];
  { const d = new Date(start); while (d <= end) { const m = sum(isoOf(d)); if (m>0) winVals.push(m); d.setDate(d.getDate()+1); } }
  const sorted = [...winVals].sort((a,b)=>a-b);
  const qv = q => sorted.length ? sorted[Math.min(sorted.length-1, Math.floor(q*(sorted.length-1)))] : 0;
  const t1=qv(0.25), t2=qv(0.5), t3=qv(0.75);
  const lvl = m => m<=0?0 : sorted.length<4 ? (m>0?3:0) : m<=t1?1 : m<=t2?2 : m<=t3?3 : 4;
  const RAMP = [`rgba(${C.ink},0.08)`, "#14502e", "#1c7a42", "#2fae5f", "#4ade80"];
  // geometry (viewBox units)
  const VW=320, LEFT=18, TOP=15;
  const gap = weeks<=10 ? 3 : weeks<=26 ? 2 : 1.4;
  const cell = Math.min(40, (VW-LEFT-2-(weeks-1)*gap)/weeks);
  const gridW = weeks*cell + (weeks-1)*gap;
  const xO = LEFT + Math.max(0,(VW-LEFT-2-gridW)/2);
  const VH = TOP + 7*cell + 6*gap + 4;
  // cells + month labels
  const cells=[]; const monthLabels=[]; let lastMo=-1;
  for (let c=0;c<weeks;c++){
    for (let r=0;r<7;r++){
      const d=new Date(start); d.setDate(d.getDate()+c*7+r);
      const iso=isoOf(d);
      if (iso>today) continue;
      if (iso<firstIso) continue;
      const m=sum(iso);
      cells.push({c,r,iso,m,l:lvl(m)});
      if (r===0 || iso===firstIso){
        const mo=d.getMonth();
        if (d.getDate()<=7 && mo!==lastMo){ monthLabels.push({c, label:d.toLocaleDateString("en-US",{month:"short"})}); lastMo=mo; }
      }
    }
  }
  // stats
  const daysWindow = Math.round((end - new Date(firstIso+"T00:00:00"))/86400000)+1;
  const active = withData.filter(k=>k>=firstIso && k<=today).length;
  const back = n => { const d=new Date(end); d.setDate(d.getDate()-n); return isoOf(d); };
  let cur=0; { let n = sum(today)>0 ? 0 : 1; while (sum(back(n))>0){cur++;n++;} }
  let longest=0; { let run=0; const d=new Date(firstIso+"T00:00:00"); while(d<=end){ if(sum(isoOf(d))>0){run++; if(run>longest)longest=run;} else run=0; d.setDate(d.getDate()+1);} }
  const moTot={}; withData.forEach(k=>{ if(k>=firstIso&&k<=today) moTot[k.slice(0,7)]=(moTot[k.slice(0,7)]||0)+sum(k); });
  const topMoKey = Object.keys(moTot).sort((a,b)=>moTot[b]-moTot[a])[0];
  const topMo = topMoKey ? new Date(topMoKey+"-01T00:00:00").toLocaleDateString("en-US",{month:"short"}) : "—";
  let maxIso=null, maxM=0;
  withData.forEach(k=>{ if(k>=firstIso&&k<=today){ const m=sum(k); if(m>maxM){maxM=m; maxIso=k;} } });
  const wdTot=[0,0,0,0,0,0,0];
  withData.forEach(k=>{ if(k>=firstIso&&k<=today){ wdTot[new Date(k+"T00:00:00").getDay()]+=sum(k); } });
  const bestWd = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][wdTot.indexOf(Math.max(...wdTot))];
  const totalM = winVals.reduce((a,b)=>a+b,0);
  const avgActive = active ? Math.round(totalM/active) : 0;
  const DAYS=["S","M","T","W","T","F","S"];
  const selMins = sel!=null ? sum(sel) : 0;
  return (
    <div style={{width:"100%",padding:"2px 4px 8px",boxSizing:"border-box"}}>
      <svg width="100%" viewBox={`0 0 ${VW} ${VH}`} style={{display:"block",overflow:"visible"}}>
        {monthLabels.map(({c,label},i)=>(
          <text key={i} x={xO + c*(cell+gap)} y={TOP-4} fontSize={Math.max(7,Math.min(10,cell*0.5))} fontWeight="700" fill={`rgba(${C.ink},0.45)`}>{label}</text>
        ))}
        {DAYS.map((ch,r)=>(
          <text key={r} x={xO-4} y={TOP + r*(cell+gap) + cell*0.7} textAnchor="end" fontSize={Math.max(6,Math.min(9,cell*0.42))} fill={`rgba(${C.ink},0.35)`}>{ch}</text>
        ))}
        {cells.map(({c,r,iso,l})=>{
          const x = xO + c*(cell+gap), y = TOP + r*(cell+gap);
          const isToday = iso===today, isSel = iso===sel;
          return <rect key={iso} x={x} y={y} width={cell} height={cell} rx={Math.max(1.5,cell*0.18)}
            fill={RAMP[l]} stroke={isSel?"#d4a017":isToday?"#ffffff":"none"} strokeWidth={isSel||isToday?Math.max(1,cell*0.07):0}
            style={{cursor:"pointer"}} onClick={()=>setSel(v=>v===iso?null:iso)}/>;
        })}
      </svg>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:8,marginTop:8,flexWrap:"wrap"}}>
        <div style={{fontSize:12.5,fontWeight:700,color:C.textMid}}>
          {active}/{daysWindow} days · 🔥{cur} streak · longest {longest} · top {topMo}
          <div style={{fontWeight:600,color:C.textFaint,marginTop:2}}>
            total {fmtM(totalM)} · most {fmtM(maxM)}{maxIso?` (${parseInt(maxIso.slice(5,7))}/${parseInt(maxIso.slice(8,10))})`:""} · best day {bestWd} · avg {fmtM(avgActive)}/day
          </div>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:3}}>
          <span style={{fontSize:10,color:C.textFaint}}>Less</span>
          {RAMP.map((cc,i)=>(<span key={i} style={{width:11,height:11,borderRadius:3,background:cc,display:"inline-block"}}/>))}
          <span style={{fontSize:10,color:C.textFaint}}>More</span>
        </div>
      </div>
      {sel && (
        <div style={{display:"flex",alignItems:"center",gap:10,marginTop:8,padding:"8px 10px",borderRadius:10,border:`1px solid ${C.border}`,background:`rgba(${C.ink},0.04)`}}>
          <span style={{fontSize:13.5,fontWeight:800,color:C.text}}>{parseInt(sel.slice(5,7))}/{parseInt(sel.slice(8,10))}</span>
          <span style={{fontSize:13,fontWeight:700,color:selMins>0?"#4ade80":C.textFaint}}>{selMins>0?fmtM(selMins):"no time logged"}</span>
          <button onClick={()=>{ onOpenDay(sel); }} style={{marginLeft:"auto",padding:"5px 12px",borderRadius:8,border:"1px solid #4a90d9",background:"rgba(74,144,217,0.15)",color:"#7ab4f0",fontSize:12.5,fontWeight:800,cursor:"pointer"}}>Open ›</button>
        </div>
      )}
    </div>
  );
}

function YearGridBody({entries, today, onPick=()=>{}, fill=false, hideTitle=false, zoom: zoomProp, onZoom}) {
  const minsBy = React.useMemo(() => {
    const m = {};
    Object.keys(entries).forEach(iso => { m[iso] = (entries[iso]||[]).reduce((s,e)=>s+(e.minutes||0),0); });
    return m;
  }, [entries]);
  const fmtIso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
  const t = new Date(today+"T00:00:00");

  // Right-side zoom slider: 0 = most zoomed out (all time) … 6 = most zoomed in (last day)
  const ZOOMS = [
    {label:"All", days:null},
    {label:"5y",  days:1825},
    {label:"1y",  days:365},
    {label:"Qtr", days:90},
    {label:"Mo",  days:30},
    {label:"Wk",  days:7},
    {label:"Day", days:1},
  ];
  const [zoomInternal, setZoomInternal] = React.useState(()=>{ const v=parseInt((typeof localStorage!=="undefined"&&localStorage.getItem("jtHeatZoom"))||"2",10); return isNaN(v)?2:Math.max(0,Math.min(6,v)); });
  const zoom = (zoomProp!=null && !isNaN(zoomProp)) ? Math.max(0,Math.min(6,zoomProp)) : zoomInternal;
  const setZ = v => { if(typeof onZoom==="function") onZoom(v); else { setZoomInternal(v); try{localStorage.setItem("jtHeatZoom",String(v));}catch(e){} } };

  // Measure available height so the grid always fills the window.
  const wrapRef = React.useRef(null);
  const [availH, setAvailH] = React.useState(0);
  const [mW, setMW] = React.useState(0);
  React.useEffect(() => {
    const measure = () => { const el=wrapRef.current; if(!el) return; const r=el.getBoundingClientRect(); const vh=(typeof window!=="undefined")?window.innerHeight:740; setAvailH(Math.max(150, Math.round(vh - r.top - 70))); setMW(Math.round(el.clientWidth||r.width||0)); };
    measure();
    let ro; if (typeof ResizeObserver!=="undefined" && wrapRef.current){ ro=new ResizeObserver(measure); ro.observe(wrapRef.current); }
    if (typeof window!=="undefined") window.addEventListener("resize", measure);
    return () => { if(ro)ro.disconnect(); if(typeof window!=="undefined") window.removeEventListener("resize", measure); };
  }, [zoom]);

  const firstIso = Object.keys(minsBy).filter(iso => (minsBy[iso]||0)>0 && iso<=today).sort()[0];
  const zd = ZOOMS[zoom].days;
  let startIso;
  if (zd==null) startIso = firstIso || today;
  else { const s=new Date(t); s.setDate(t.getDate()-(zd-1)); startIso = fmtIso(s); }

  // Colour ramp: low → high = black → blue → yellow → white (white = most time with Jesus)
  const activeVals = [];
  { let d=new Date(startIso+"T00:00:00"); for(; d<=t; d.setDate(d.getDate()+1)){ const m=minsBy[fmtIso(d)]||0; if(m>0) activeVals.push(m); } }
  activeVals.sort((a,b)=>a-b);
  const valsDesc = activeVals.slice().sort((a,b)=>b-a);
  const nAct = valsDesc.length;
  const qd = p => nAct ? valsDesc[Math.min(Math.floor(p*nAct), nAct-1)] : Infinity;
  const tA=qd(0.20), tB=qd(0.40), tC=qd(0.60), tD=qd(0.80);
  const BANDS=[[50,185,90,1.0],[210,185,30,0.6],[220,120,40,0.4],[200,60,60,0.2]];
  const bandOf = m => { if(m<=0||!nAct) return -1; if(m>=tA)return 0; if(m>=tB)return 1; if(m>=tC)return 2; if(m>=tD)return 3; return -1; };
  const BG=[24,16,8];
  const sqBg = m => { const b=bandOf(m); return b>=0 ? `rgba(${BANDS[b][0]},${BANDS[b][1]},${BANDS[b][2]},${BANDS[b][3]})` : `rgba(${C.ink},0.07)`; };
  const txtFor = m => { const b=bandOf(m); let rgb; if(b<0) rgb=BG; else { const a=BANDS[b][3]; rgb=[0,1,2].map(i=>Math.round(BANDS[b][i]*a+BG[i]*(1-a))); } const lum=(0.299*rgb[0]+0.587*rgb[1]+0.114*rgb[2])/255; return lum>0.6?"#1a1408":"#f3ecdd"; };
  const fmtMin = m => m>=60 ? `${Math.floor(m/60)}h${m%60?(m%60)+"m":""}` : `${m}m`;

  const dayList = [];
  { let d=new Date(startIso+"T00:00:00"); for(; d<=t; d.setDate(d.getDate()+1)) dayList.push(fmtIso(d)); }

  const availW = (mW>0 ? mW : Math.min((typeof window!=="undefined"?window.innerWidth:680),680)) - 2;
  const gh = availH || 360;
  const gap = 3;
  const monStr = iso => { const p=(iso||"").split("-"); return p.length===3?`${+p[1]}/${p[0].slice(2)}`:""; };
  const WD = ["Su","Mo","Tu","We","Th","Fr","Sa"];


  let gridEl;
  if (dayList.length <= 10) {
    const n = dayList.length;
    // fill both width and height: pick the row count that maximizes tile size
    let best={cell:0,cols:n,rows:1};
    for (let r=1;r<=n;r++){ const cols=Math.ceil(n/r); const cw=(availW-(cols-1)*gap)/cols; const ch=(gh-(r-1)*gap)/r; const c=Math.min(cw,ch); if(c>best.cell) best={cell:c,cols,rows:r}; }
    const cell=Math.max(34,Math.min(260,Math.floor(best.cell)));
    gridEl = (
      <div style={{display:"flex",gap:gap,flexWrap:"wrap",justifyContent:"center",alignContent:"center",height:gh,maxWidth:best.cols*(cell+gap),marginLeft:"auto",marginRight:"auto"}}>
        {dayList.map(iso=>{
          const m=minsBy[iso]||0; const isToday=iso===today; const tc=txtFor(m);
          const d=new Date(iso+"T00:00:00");
          return (
            <div key={iso} onClick={()=>onPick(iso)} title={iso}
              style={{width:cell,height:cell,borderRadius:Math.max(3,cell*0.1),cursor:"pointer",position:"relative",
                outline:isToday?`2px solid ${C.gold}`:"none",outlineOffset:-1,background:sqBg(m),
                display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:2}}>
              <span style={{fontSize:Math.max(11,Math.round(cell*0.14)),fontWeight:700,color:tc,opacity:0.85}}>{WD[d.getDay()]} {d.getDate()}</span>
              {m>0 && <span style={{fontSize:Math.max(13,Math.round(cell*0.19)),fontWeight:800,color:tc}}>{fmtMin(m)}</span>}
            </div>
          );
        })}
      </div>
    );
  } else {
    const startD = new Date(startIso+"T00:00:00");
    const startSun = new Date(startD); startSun.setDate(startD.getDate()-startD.getDay());
    const endSat = new Date(t); endSat.setDate(t.getDate()+(6-t.getDay()));
    const WEEKS = Math.round((endSat-startSun)/(7*86400000))+1;
    const cols=[];
    for (let w=0; w<WEEKS; w++){ const col=[]; for(let dd=0;dd<7;dd++){ const dt=new Date(startSun); dt.setDate(startSun.getDate()+w*7+dd); const iso=fmtIso(dt); col.push({iso, m:minsBy[iso]||0, future: iso>today, before: iso<startIso}); } cols.push(col); }
    // choose weeks-per-row + cell so the whole grid fills BOTH width and height
    const LABEL=20, ROWGAP=8;
    // pick number of bands (rows); balanced weeks per row; biggest cells that fill the width yet still fit the height
    let best=null;
    for (let nr=1; nr<=WEEKS; nr++){
      const wpr=Math.ceil(WEEKS/nr);
      const cw=(availW - wpr*gap)/wpr;                         // reserve a trailing gap so a full row never overflows right
      const ch=(gh - nr*(LABEL+6*gap) - (nr-1)*ROWGAP)/(nr*7);
      const c=Math.min(cw,ch);
      if (c<4) continue;
      const fill=Math.min(1,(wpr*c + (wpr-1)*gap)/availW);
      const score=c*fill;                                      // reward big cells AND filling the width
      if (!best || score>best.score) best={score,wpr,nr,c};
    }
    if(!best){ const wpr=Math.max(1,Math.floor((availW+gap)/(5+gap))); best={wpr,nr:Math.ceil(WEEKS/wpr),c:5}; }
    const cell=Math.max(4,Math.min(96,Math.floor(best.c)));
    let weeksPerRow=Math.min(Math.max(1,best.wpr), Math.max(1,Math.floor((availW+gap)/(cell+gap))));
    const radius=Math.max(1.5,cell*0.2);
    const showNum = cell>=24;
    const monthStart=new Set(); { let pm=null; cols.forEach(col=>{ const mk=(col[0].iso||"").slice(0,7); if(mk!==pm){monthStart.add(col[0].iso);pm=mk;} }); }
    const rows=[]; for(let i=0;i<cols.length;i+=weeksPerRow) rows.push(cols.slice(i,i+weeksPerRow));
    rows.reverse(); // newest weeks on top
    gridEl = (
      <div style={{display:"flex",flexDirection:"column",gap:ROWGAP,alignItems:"center",justifyContent:"center",minHeight:gh}}>
        {rows.map((rowCols,ri)=>(
          <div key={ri} style={{display:"flex",flexDirection:"column",alignItems:"flex-start",gap:2}}>
            <div style={{display:"flex",gap:gap,height:LABEL}}>
              {rowCols.map((col,ci)=>(
                <div key={ci} style={{width:cell,position:"relative"}}>
                  {monthStart.has(col[0].iso) && <span style={{position:"absolute",left:0,bottom:0,fontSize:14,fontWeight:800,color:C.textFaint,whiteSpace:"nowrap",lineHeight:1}}>{monStr(col[0].iso)}</span>}
                </div>
              ))}
            </div>
            <div style={{display:"flex",gap:gap}}>
              {rowCols.map((col,ci)=>(
                <div key={ci} style={{display:"flex",flexDirection:"column",gap:gap}}>
                  {col.map(({iso,m,future,before})=>{
                    if (future||before) return <div key={iso} style={{width:cell,height:cell,borderRadius:radius,background:"transparent"}}/>;
                    const isToday=iso===today; const tc=txtFor(m);
                    return (
                      <div key={iso} title={`${iso}${m?" · "+fmtMin(m):""}`} onClick={()=>onPick(iso)}
                        style={{width:cell,height:cell,borderRadius:radius,cursor:"pointer",position:"relative",
                          outline:isToday?`2px solid ${C.gold}`:"none",outlineOffset:-1,background:sqBg(m),
                          display:showNum?"flex":"block",alignItems:"center",justifyContent:"center"}}>
                        {showNum && <span style={{fontSize:Math.max(8,Math.round(cell*0.34)),fontWeight:700,color:tc,lineHeight:1}}>{+iso.slice(8,10)}</span>}
                      </div>
                    );
                  })}
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    );
  }

  return (
    <div style={{margin:"0 0 8px",paddingTop:hideTitle?28:30}}>
      {!hideTitle && (
        <div style={{fontSize:12,letterSpacing:"0.1em",textTransform:"uppercase",color:C.textFaint,fontWeight:800,padding:"2px 4px 2px"}}>
          📅 Last Year with Jesus
        </div>
      )}
      <div ref={wrapRef} style={{display:"flex",alignItems:"stretch",height:availH||undefined}}>
        <div style={{flex:1,minWidth:0,overflow:"hidden"}}>{gridEl}</div>
      </div>
    </div>
  );
}

function CelebrationBurst() {
  const embers = [[-46,-12,2.6,0],[-18,-28,2,0.15],[12,-20,2.8,0.05],[40,-10,2.2,0.2],[-32,6,1.8,0.3],[26,2,2.4,0.25],[0,-36,1.6,0.1],[52,-24,1.8,0.35]];
  return (
    <div style={{position:"fixed",inset:0,zIndex:120,pointerEvents:"none",
      display:"flex",alignItems:"center",justifyContent:"center"}}>
      <div style={{position:"relative",width:0,height:0}}>
        <div style={{position:"absolute",left:-110,top:-110,width:220,height:220,borderRadius:"50%",
          border:"2.5px solid #d4a017",
          boxShadow:"0 0 30px rgba(212,160,23,0.55), inset 0 0 22px rgba(212,160,23,0.25)",
          animation:"jtRingBloom 1.7s ease-out both"}}/>
        {embers.map(([x,y,r,d],i)=>(
          <div key={i} style={{position:"absolute",left:x,top:y,width:r*2,height:r*2,borderRadius:"50%",
            background:"#d4a017",boxShadow:"0 0 6px rgba(212,160,23,0.9)",
            animation:`jtEmberRise 1.9s ease-out ${d}s both`}}/>
        ))}
        <div style={{position:"absolute",left:-130,top:124,width:260,textAlign:"center",
          fontSize:14,fontWeight:800,color:"#d4a017",textShadow:"0 0 12px rgba(212,160,23,0.6)",
          animation:"jtCelebText 2.3s ease-out both"}}>
          ✝ Today's circle complete
        </div>
      </div>
    </div>
  );
}


function TripleArc({morningMins, middayMins, eveningMins, totalPct, totalMins, size=110, stroke=10, numDays=1, onSlotTap=null, timeline=null, showNow=false, elapsedGray=false, stackTop=false, nowIcon=null, avgLineMins=null, showRunner=false, baseFill=null, nowIconLabel=null}) {
  const cx = size/2, cy = size/2, r = (size-stroke)/2;
  const mc = "#2a5ab8", dc = "#3aaa55", ec = "#e05a18";
  const total = morningMins + middayMins + eveningMins;
  const n = Math.max(1, numDays);

  // Animated sweep: tween displayed minutes toward targets (and from 0 on mount)
  const [anim, setAnim] = React.useState({m:0, d:0, e:0});
  const animRef = React.useRef({m:0, d:0, e:0});
  React.useEffect(() => {
    const target = {m:morningMins, d:middayMins, e:eveningMins};
    const reduce = typeof window !== "undefined" && window.matchMedia
      && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) { animRef.current = target; setAnim(target); return; }
    const from = {...animRef.current};
    if (from.m===target.m && from.d===target.d && from.e===target.e) return;
    const t0 = performance.now(), DUR = 600;
    let raf;
    const step = now => {
      const t = Math.min(1, (now - t0) / DUR);
      const ease = 1 - Math.pow(1 - t, 3);
      const cur = {
        m: from.m + (target.m - from.m) * ease,
        d: from.d + (target.d - from.d) * ease,
        e: from.e + (target.e - from.e) * ease,
      };
      animRef.current = cur; setAnim(cur);
      if (t < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [morningMins, middayMins, eveningMins]);

  // Helper: polar to cartesian
  const polar = (angleDeg, radius) => ({
    x: cx + radius * Math.cos((angleDeg - 90) * Math.PI / 180),
    y: cy + radius * Math.sin((angleDeg - 90) * Math.PI / 180),
  });

  const slotTapProps = slot => onSlotTap ? {
    onClick: e => { e.stopPropagation(); onSlotTap(slot); },
    style: {cursor:"pointer"},
  } : {};

  // Build a filled pie sector path
  const sector = (startDeg, endDeg, color, key, slot) => {
    if (endDeg - startDeg <= 0) return null;
    const large = endDeg - startDeg > 180 ? 1 : 0;
    const p1 = polar(startDeg, r);
    const p2 = polar(endDeg, r);
    const d = `M ${cx} ${cy} L ${p1.x} ${p1.y} A ${r} ${r} 0 ${large} 1 ${p2.x} ${p2.y} Z`;
    return <path key={key} d={d} fill={color} {...slotTapProps(slot)}/>;
  };

  // Three equal 120° sectors — caps scale by number of days in the period
  const GAP = 2;
  const sectors = [
    {mins: anim.m, cap: 300 * n, color: mc, start: 0,   span: 120 - GAP, slot: "morning"},
    {mins: anim.d, cap: 300 * n, color: dc, start: 120, span: 120 - GAP, slot: "midday"},
    {mins: anim.e, cap: 360 * n, color: ec, start: 240, span: 120 - GAP, slot: "evening"},
  ];

  // Clock mode (day view): the interior fills at the actual time of day. 6:00 at top, clockwise.
  const clockMode = !!timeline;
  const clockAngle = mins => { const m = Math.min(900, Math.max(0, mins - 420)); return m / 900 * 360; }; // 15h face: 7:00 → 0° (top), 22:00 → 360°
  // Slot tap zones by clock time (within 7a–10p face): morning 7–11, midday 11–16, evening 16–22
  const clockTapZones = [
    {slot:"morning", a0:clockAngle(7*60),   span:clockAngle(11*60) - clockAngle(7*60)},
    {slot:"midday",  a0:clockAngle(11*60),  span:clockAngle(16*60) - clockAngle(11*60)},
    {slot:"evening", a0:clockAngle(16*60),  span:360 - clockAngle(16*60)},
  ];
  const slotColor = s => s==="morning" ? mc : s==="midday" ? dc : ec;

  return (
    <svg width={size} height={size} style={{display:"block",flexShrink:0,overflow:"visible"}}>
      {/* Background circle */}
      <circle cx={cx} cy={cy} r={r} fill={baseFill||C.arcBg}/>
      {/* Track outlines — tappable even when a slot is empty */}
      {(clockMode ? clockTapZones.map(({slot,a0,span})=>({start:a0, span, slot})) : sectors)
        .map(({start, span, slot}, i) => {
        const p1 = polar(start, r);
        const p2 = polar(start + span, r);
        const large = span > 180 ? 1 : 0;
        return <path key={`t${i}`}
          d={`M ${cx} ${cy} L ${p1.x} ${p1.y} A ${r} ${r} 0 ${large} 1 ${p2.x} ${p2.y} Z`}
          fill={baseFill||C.arcBg} {...slotTapProps(slot)}/>;
      })}
      {clockMode && showNow && elapsedGray && (()=>{
        const nw = new Date();
        const a = clockAngle(nw.getHours()*60 + nw.getMinutes());
        if (a <= 0.5) return null;
        const p1 = polar(0, r), p2 = polar(a, r);
        const large = a > 180 ? 1 : 0;
        return <path d={`M ${cx} ${cy} L ${p1.x} ${p1.y} A ${r} ${r} 0 ${large} 1 ${p2.x} ${p2.y} Z`}
          fill="rgba(150,150,150,0.30)" pointerEvents="none"/>;
      })()}
      {clockMode && stackTop ? (
        /* Cumulative fill from top: colored by slot, grows as time is added */
        (()=>{ const DM=15*60; const parts=[["morning",mc,anim.m],["midday",dc,anim.d],["evening",ec,anim.e]]; let acc=0; return parts.map(([sl,cl,mn],i)=>{ if(mn<=0) return null; const a0=acc/DM*360; acc+=mn; const a1=Math.min(360,acc/DM*360); return sector(a0,a1,cl,`st${i}`,sl); }); })()
      ) : clockMode ? (
        /* Clock fill: each entry a wedge at its actual time of day */
        [...timeline].sort((a,b)=>(a.ts||0)-(b.ts||0)).map((e,i)=>{
          const d = new Date(e.ts);
          const a0 = clockAngle(d.getHours()*60 + d.getMinutes());
          const sweep = Math.max(4, ((e.minutes||0)/1440)*360);
          return sector(a0, a0 + sweep, slotColor(getTimeSlot(e.ts)), `c${i}`, getTimeSlot(e.ts));
        })
      ) : (
        /* Filled sectors proportional to time */
        sectors.map(({mins, cap, color, start, span, slot}, i) => {
          const fill = Math.min(1, mins / cap);
          if (fill <= 0) return null;
          const filledSpan = fill * span;
          return sector(start, start + filledSpan, color, `f${i}`, slot);
        })
      )}
      {/* Divider lines at slot boundaries */}
      {!baseFill && (clockMode ? [clockAngle(11*60), clockAngle(16*60), clockAngle(0)] : [0, 120, 240]).map((deg, i) => {
        const p = polar(deg, r);
        return <line key={`d${i}`} x1={cx} y1={cy} x2={p.x} y2={p.y}
          stroke="rgba(20,12,4,0.8)" strokeWidth="2" pointerEvents="none"/>;
      })}
      {/* Average-pace dotted line: where logged time should be by now */}
      {clockMode && avgLineMins!=null && (()=>{
        const deg = Math.min(360, avgLineMins/(15*60)*360);
        const p = polar(deg, r);
        const lp2 = polar(deg, r - 14);
        return <g pointerEvents="none">
          <line x1={cx} y1={cy} x2={p.x} y2={p.y}
            stroke="#d4a017" strokeWidth="2.4" strokeDasharray="5 5"
            style={{filter:"drop-shadow(0 0 2px rgba(0,0,0,0.7))"}}/>
          <text x={lp2.x} y={lp2.y} textAnchor="middle" dominantBaseline="central"
            fontSize="11" fontWeight="800" fill="#d4a017"
            style={{filter:"drop-shadow(0 0 2px rgba(0,0,0,0.8))"}}>avg</text>
        </g>;
      })()}
      {/* Outer border ring — gold glow at 50%+ replaces the old star ring */}
      <circle cx={cx} cy={cy} r={r} fill="none"
        stroke={totalPct >= 50 ? "#d4a017" : `rgba(${C.ink},0.45)`}
        strokeWidth={totalPct >= 50 ? 2.5 : 2}
        pointerEvents="none"
        style={totalPct >= 50 ? {filter:"drop-shadow(0 0 6px rgba(212,160,23,0.85))", transition:"all .4s ease"} : {transition:"all .4s ease"}}/>
      {/* NOW — riding the one border */}
      {clockMode && showNow && (()=>{
        const nw = new Date();
        const a = clockAngle(nw.getHours()*60 + nw.getMinutes());
        const p = polar(a, r);
        const lp = polar(a, r - 22);
        if (nowIcon) {
          const totJ = anim.m + anim.d + anim.e;
          const elapsedJ = Math.min(900, Math.max(0, (nw.getHours()*60 + nw.getMinutes()) - 420));
          const gapJ = Math.max(0, elapsedJ - totJ);
          const baseJ = size/2;   // caught up → half the circle
          const isz = totJ <= 0 ? 48 : Math.max(48, baseJ - (baseJ - 20) * Math.min(1, gapJ/480));   // shrinks over an 8h gap
          const ip = polar(a, r - isz/2 + 1);
          return <g pointerEvents="none">
            <image href={nowIcon} x={ip.x - isz/2} y={ip.y - isz/2} width={isz} height={isz}
              style={{filter:"drop-shadow(0 0 5px rgba(212,160,23,0.85))"}}/>
            {nowIconLabel && <text x={ip.x + (a<=180 ? isz*0.36 : -isz*0.36)} y={ip.y + isz*0.21 - 5} textAnchor="middle" fontSize={Math.max(8, isz*0.12)} fontWeight="800"
              fill="#d4a017" style={{filter:"drop-shadow(0 0 3px rgba(0,0,0,0.9))"}}>{nowIconLabel}</text>}
          </g>;
        }
        return <g pointerEvents="none">
          <circle cx={p.x} cy={p.y} r={5} fill="#ffffff" stroke="#d4a017" strokeWidth={2.2}
            style={{filter:"drop-shadow(0 0 5px rgba(212,160,23,0.9))"}}/>
          <text x={lp.x} y={lp.y+4} textAnchor="middle" fontSize="13" fontWeight="800"
            fill="#ffffff" letterSpacing="0.08em"
            style={{filter:"drop-shadow(0 0 3px rgba(0,0,0,0.8))"}}>NOW</text>
        </g>;
      })()}
      {/* Runner at your accumulated-time position — drawn after NOW so the boy sits in front of Jesus */}
      {clockMode && showRunner && (()=>{
        const tot = anim.m + anim.d + anim.e;
        if (tot <= 0) return null;
        const deg = Math.min(360, tot/(15*60)*360);
        const nwR = new Date();
        const elapsedR = Math.min(900, Math.max(0, (nwR.getHours()*60 + nwR.getMinutes()) - 420));
        const gapR = Math.max(0, elapsedR - tot);   // minutes behind "now"
        // mirror Jesus' current size/position so we can detect overlap
        const baseJ = size/2;
        const jIsz = Math.max(48, baseJ - (baseJ - 20) * Math.min(1, gapR/480));
        const isz = Math.max(14, jIsz * 0.5);   // boy is always half of Jesus
        const aJ = Math.min(360, elapsedR/900*360);
        const jp = polar(aJ, r - jIsz/2 + 1);
        const p = polar(deg, r - isz/2 - 4);
        const onJesus = Math.hypot(p.x - jp.x, p.y - jp.y) < jIsz/2;
        let bx = p.x, by = p.y;
        if (onJesus) {   // stand on his body, just below the head
          bx = jp.x;
          by = jp.y - jIsz/2 + jIsz*0.62 - (gapR <= 0 ? 30 : 0);
        }
        return <g pointerEvents="none">
          <image href={RUNNER_ICON} x={bx - isz/2} y={by - isz/2} width={isz} height={isz}
            style={{filter:"drop-shadow(0 0 4px rgba(0,0,0,0.7))"}}/>
        </g>;
      })()}
    </svg>
  );
}


const PTABS = {
  week:"#ffffff", month:"#c06080", year:"#6090c0", all:"#60a060", l365:"#a060c0",
  label:{week:"Week", month:"Month", year:"Year to date", all:"3.5 Yrs", l365:"Last 365d"}
};
function todayKey() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
}
function pct(m)  { return Math.min(100, Math.round((m/WAKE)*1000)/10); }
function fmtM(m) {
  if (!m) return ":00";
  const h = Math.floor(m/60), r = m%60;
  return h > 0 ? `${h}:${String(r).padStart(2,'0')}` : `:${String(r).padStart(2,'0')}`;
}
function fmtMRaw(m) {
  if (!m) return "0m";
  if (m < 60) return m+"m";
  const h = Math.floor(m/60), r = m%60;
  return r ? h+"hr "+r+"m" : h+"hr";
}
function fmtDate(iso) {
  const [y,mo,d] = iso.split("-");
  return new Date(+y,+mo-1,+d).toLocaleDateString("en-US",{weekday:"short",month:"short",day:"numeric"});
}
