// LXX (Rahlfs) Psalm number -> Hebrew/ESV Psalm number, and reverse. Other books align at chapter level.
function lxxPsToEsv(n){ if(n<=8) return n; if(n===9) return 9; if(n<=112) return n+1; if(n===113) return 114; if(n===114||n===115) return 116; if(n<=145) return n+1; if(n===146||n===147) return 147; return n; }
function esvPsToLxx(m){ if(m<=8) return m; if(m===9||m===10) return 9; if(m<=113) return m-1; if(m===114||m===115) return 113; if(m===116) return 114; if(m<=146) return m-1; if(m===147) return 146; return m; }
function gkNorm(s){ return (s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/ς/g,"σ"); }
function gkTranslit(word){
  if(!word) return "";
  const tokens=[];
  for(const c of word.normalize("NFD")){
    if(/[\u0300-\u036f]/.test(c)){ if(tokens.length) tokens[tokens.length-1].m.push(c); }
    else tokens.push({c, m:[]});
  }
  const map={'α':'a','β':'b','γ':'g','δ':'d','ε':'e','ζ':'z','η':'ē','θ':'th','ι':'i','κ':'k','λ':'l','μ':'m','ν':'n','ξ':'x','ο':'o','π':'p','ρ':'r','σ':'s','ς':'s','τ':'t','υ':'y','φ':'ph','χ':'ch','ψ':'ps','ω':'ō'};
  let out="";
  for(let k=0;k<tokens.length;k++){
    const ch=tokens[k].c.toLowerCase();
    let base=map[ch];
    if(base===undefined){ out+=tokens[k].c; continue; }
    if(ch==='γ'){ const nx=tokens[k+1]&&tokens[k+1].c.toLowerCase(); if(nx&&'γκξχ'.includes(nx)) base='n'; }
    if(ch==='υ'){ const pv=tokens[k-1]&&tokens[k-1].c.toLowerCase(); if(pv&&'αεηο'.includes(pv)) base='u'; }
    if(tokens[k].m.includes('\u0314')){ base = ch==='ρ' ? 'rh' : 'h'+base; }
    out+=base;
  }
  return out;
}



// Long-form reading texts are served as static assets (/data/*.json) and fetched on demand,
// to keep the Worker bundle small. They start empty and populate when a book is first opened.
const BOOK_DATA_URLS = { disciple:"/data/disciple.json", pilgrim:"/data/pilgrim.json", witnesses:"/data/witnesses.json", checkbook:"/data/checkbook.json", burial:"/data/burial.json", dagg:"/data/dagg.json" };
const _bookDataCache = {};
function applyBookData(id, arr){
  _bookDataCache[id] = arr;
  if(id==="disciple") DISCIPLE_PARAS = arr;
  else if(id==="pilgrim") PP_PARAS = arr;
  else if(id==="witnesses") WITNESSES_PARAS = arr;
  else if(id==="checkbook") CHECKBOOK_DAYS = arr;
  else if(id==="burial") BURIAL_PARAS = arr;
  else if(id==="dagg") DAGG_PARAS = arr;
}
function loadBookData(id){
  if(_bookDataCache[id]) return Promise.resolve(_bookDataCache[id]);
  const url = BOOK_DATA_URLS[id];
  if(!url) return Promise.resolve(null);
  return fetch(url).then(r=>{ if(!r.ok) throw new Error("HTTP "+r.status); return r.json(); }).then(arr=>{ applyBookData(id, arr); return arr; });
}

